        return cat->keys_count;
    } else {
        cat->keys_movable = 0;
        return commandCatalogExtractLegacyRange(cat,cmd,argv,argc,result);
    }
}

int commandCatalogExtractGeneric(commandCatalog *cat, int storeKeyOfs, int keyCountOfs, int firstKeyOfs, int keyStep,
                    robj **argv, int argc, getKeysResult *result) {
    int i, num, *keys;
    cat->keys_argv = argv;
