    cat->keys_store_ofs = storeKeyOfs;
    cat->keys_count_ofs = keyCountOfs;
    cat->keys_first = firstKeyOfs;
    cat->keys_step = keyStep;

    num = atoi(argv[keyCountOfs]->ptr);
    /* Sanity check. Don't return any key if the command is going to
     * reply with syntax error. (no input keys). */
    if (num < 1 || num > (argc - firstKeyOfs)/keyStep) {
        result->numkeys = 0;
        cat->keys_count = 0;
        return 0;
    }

    int numkeys = storeKeyOfs ? num + 1 : num;
    keys = commandCatalogPrepareKeys(cat, result, numkeys);
    result->numkeys = numkeys;
    cat->keys_count = numkeys;

    /* Add all key positions for argv[firstKeyOfs...n] to keys[] */
    for (i = 0; i < num; i++) {
        keys[i] = firstKeyOfs+(i*keyStep);
        cat->last_key_index = keys[i];
    }

    if (storeKeyOfs) {
        keys[num] = storeKeyOfs;
        cat->last_key_index = storeKeyOfs;
    }
    return result->numkeys;
}

