        c->flags |= CMD_READONLY|CMD_CATEGORY_READ;
        cat->flag_mask = c->flags;
        return 1;
    } else if (!strcasecmp(flag,"use-memory")) {
        c->flags |= CMD_DENYOOM;
        cat->flag_mask = c->flags;
        return 1;
    } else if (!strcasecmp(flag,"admin")) {
        c->flags |= CMD_ADMIN|CMD_CATEGORY_ADMIN|CMD_CATEGORY_DANGEROUS;
        cat->flag_mask = c->flags;
        return 1;
    } else if (!strcasecmp(flag,"pub-sub")) {
        c->flags |= CMD_PUBSUB|CMD_CATEGORY_PUBSUB;
        cat->flag_mask = c->flags;
        return 1;
    }
    return 0;
}

int commandCatalogApplyRuntimeFlag(commandCatalog *cat, const char *flag) {
    struct redisCommand *c = cat->flag_cmd;
    cat->flag_token = (char *)flag;
    if (!c || !flag) {
        cat->flag_error = 1;
        return 0;
    }
    if (!strcasecmp(flag,"no-script")) {
        c->flags |= CMD_NOSCRIPT;
        cat->flag_mask = c->flags;
        return 1;
    } else if (!strcasecmp(flag,"random")) {
        c->flags |= CMD_RANDOM;
        cat->flag_mask = c->flags;
        return 1;
    } else if (!strcasecmp(flag,"to-sort")) {
        c->flags |= CMD_SORT_FOR_SCRIPT;
        cat->flag_mask = c->flags;
        return 1;
    } else if (!strcasecmp(flag,"ok-loading")) {
        c->flags |= CMD_LOADING;
        cat->flag_mask = c->flags;
        return 1;
    } else if (!strcasecmp(flag,"ok-stale")) {
        c->flags |= CMD_STALE;
        cat->flag_mask = c->flags;
        return 1;
    }
    return 0;
}

int commandCatalogApplyObservabilityFlag(commandCatalog *cat, const char *flag) {
    struct redisCommand *c = cat->flag_cmd;
    cat->flag_token = (char *)flag;
    if (!c || !flag) {
        cat->flag_error = 1;
        return 0;
    }
    if (!strcasecmp(flag,"no-monitor")) {
        c->flags |= CMD_SKIP_MONITOR;
        cat->flag_mask = c->flags;
        return 1;
    } else if (!strcasecmp(flag,"no-slowlog")) {
        c->flags |= CMD_SKIP_SLOWLOG;
        cat->flag_mask = c->flags;
        return 1;
    } else if (!strcasecmp(flag,"cluster-asking")) {
        c->flags |= CMD_ASKING;
        cat->flag_mask = c->flags;
        return 1;
    }
    return 0;
}

int commandCatalogApplyRoleFlag(commandCatalog *cat, const char *flag) {
    struct redisCommand *c = cat->flag_cmd;
    cat->flag_token = (char *)flag;
    if (!c || !flag) {
        cat->flag_error = 1;
        return 0;
    }
    if (!strcasecmp(flag,"fast")) {
        c->flags |= CMD_FAST | CMD_CATEGORY_FAST;
        cat->flag_mask = c->flags;
        return 1;
    } else if (!strcasecmp(flag,"no-auth")) {
        c->flags |= CMD_NO_AUTH;
        cat->flag_mask = c->flags;
        return 1;
    } else if (!strcasecmp(flag,"may-replicate")) {
        c->flags |= CMD_MAY_REPLICATE;
        cat->flag_mask = c->flags;
        return 1;
    } else if (!strcasecmp(flag,"sentinel")) {
        c->flags |= CMD_SENTINEL;
        cat->flag_mask = c->flags;
        return 1;
    } else if (!strcasecmp(flag,"only-sentinel")) {
        c->flags |= CMD_SENTINEL; /* Obviously it's s sentinel command */
        c->flags |= CMD_ONLY_SENTINEL;
        cat->flag_mask = c->flags;
        return 1;
    }
    return 0;
}

int commandCatalogApplyCategoryFlag(commandCatalog *cat, const char *flag) {
    struct redisCommand *c = cat->flag_cmd;
    uint64_t catflag;
    cat->flag_token = (char *)flag;
    if (!c || !flag) {
        cat->flag_error = 1;
        return 0;
    }
    if (flag[0] == '@' &&
        (catflag = ACLGetCommandCategoryFlagByName(flag+1)) != 0)
    {
        c->flags |= catflag;
        cat->flag_mask = c->flags;
        return 1;
    }
    cat->flag_error = 1;
    return 0;
}

void commandCatalogFinishFlags(commandCatalog *cat) {
    struct redisCommand *c = cat->flag_cmd;
    if (!c) {
        cat->flag_error = 1;
        return;
    }
    /* If it's not @fast is @slow in this binary world. */
    if (!(c->flags & CMD_CATEGORY_FAST)) c->flags |= CMD_CATEGORY_SLOW;
    cat->flag_mask = c->flags;
}

void commandCatalogParseFlags(commandCatalog *cat, struct redisCommand *c, char *strflags) {
    commandCatalogBindFlagCommand(cat, c, strflags);
    cat->flag_argv = sdssplitargs(strflags, &cat->flag_argc);

